11	#ifndef METADEF_CXX_INC_EXE_GRAPH_RUNTIME_EXTENDED_KERNEL_CONTEXT_H_
12	#define METADEF_CXX_INC_EXE_GRAPH_RUNTIME_EXTENDED_KERNEL_CONTEXT_H_
13	#include <type_traits>
14	#include "kernel_context.h"
15	#include "context_extend.h"
16	
17	namespace gert {
18	class ExtendedKernelContext : protected KernelContext {
19	 public:
20	  /**
21	   * 根据index获取节点输入的Tensor description
22	   * @param index 输入index
23	   * @return 输入TensorDesc的指针，index非法时，返回空指针
24	   */
25	  const CompileTimeTensorDesc *GetInputDesc(const size_t index) const {
26	    const auto compute_node_info = GetComputeNodeInfo();
27	    if (compute_node_info == nullptr) {
28	      return nullptr;
29	    }
30	    return compute_node_info->GetInputTdInfo(index);
31	  }
32	  /**
33	   * 基于算子IR原型定义，获取`OPTIONAL_INPUT`类型的输入CompileTimeTensorDesc指针
34	   * @param ir_index IR原型定义中的index
35	   * @return CompileTimeTensorDesc指针，index非法，或该INPUT没有实例化时，返回空指针
36	   */
37	  const CompileTimeTensorDesc *GetOptionalInputDesc(const size_t ir_index) const {
38	    return GetDynamicInputDesc(ir_index, 0);
39	  }
40	  /**
41	   * 基于算子IR原型定义，获取`REQUIRED_INPUT`类型的输入CompileTimeTensorDesc指针
42	   * @param ir_index IR原型定义中的index
43	   * @return CompileTimeTensorDesc指针，index非法，或该OUTPUT没有实例化时，返回空指针
44	   */
45	  const CompileTimeTensorDesc *GetRequiredInputDesc(const size_t ir_index) const {
46	    return GetDynamicInputDesc(ir_index, 0);
47	  }
48	  /**
49	   * 基于算子IR原型定义，获取`DYNAMIC_INPUT`类型的输入CompileTimeTensorDesc指针
50	   * @param ir_index IR原型定义中的index
51	   * @param relative_index
52	   * 该输入实例化后的相对index，例如某个DYNAMIC_INPUT实例化了3个输入，那么relative_index的有效范围是[0,2]
53	   * @return CompileTimeTensorDesc指针，index或relative_index非法时，返回空指针
54	   */
55	  const CompileTimeTensorDesc *GetDynamicInputDesc(const size_t ir_index, const size_t relative_index) const {
56	    const auto compute_node_info = GetComputeNodeInfo();
57	    if (compute_node_info == nullptr) {
58	      return nullptr;
59	    }
60	    const auto ins_info = GetIrInputInstanceInfo(ir_index);
61	    if (ins_info == nullptr) {
62	      return nullptr;
63	    }
64	    if (ins_info->GetInstanceNum() <= relative_index) {
65	      return nullptr;
66	    }
67	    return compute_node_info->GetInputTdInfo(ins_info->GetInstanceStart() + relative_index);
68	  }
69	  /**
70	   * 根据index获取节点输出的Tensor description
71	   * @param index 输出index
72	   * @return 输出TensorDesc的指针，index非法时，返回空指针
73	   */
74	  const CompileTimeTensorDesc *GetOutputDesc(const size_t index) const {
75	    const auto compute_node_info = GetComputeNodeInfo();
76	    if (compute_node_info == nullptr) {
77	      return nullptr;
78	    }
79	    return compute_node_info->GetOutputTdInfo(index);
80	  }
81	  /**
82	   * 根据IR原型中的index，获取在节点上的输入实例化信息
83	   * @param ir_index IR原型中定义的index
84	   * @return 实例化信息
85	   */
86	  const AnchorInstanceInfo *GetIrInputInstanceInfo(const size_t ir_index) const {
87	    const auto compute_node_info = GetComputeNodeInfo();
88	    if (compute_node_info == nullptr) {
89	      return nullptr;
90	    }
91	    return compute_node_info->GetInputInstanceInfo(ir_index);
92	  }
93	
94	  /**
95	   * 根据IR原型中的index，获取在节点上的输出实例化信息
96	   * @param ir_index IR原型中定义的index
97	   * @return 实例化信息
98	   */
99	  const AnchorInstanceInfo *GetIrOutputInstanceInfo(const size_t ir_index) const {
100	    const auto compute_node_info = GetComputeNodeInfo();
101	    if (compute_node_info == nullptr) {
102	      return nullptr;
103	    }
104	    return compute_node_info->GetOutputInstanceInfo(ir_index);
105	  }
106	
107	  /**
108	   * 获取计算节点的输入数量
109	   * @return 计算节点的输入数量
110	   */
111	  size_t GetComputeNodeInputNum() const {
112	    const auto compute_node_info = GetComputeNodeInfo();
113	    if (compute_node_info == nullptr) {
114	      return 0;
115	    }
116	    return compute_node_info->GetInputsNum();
117	  }
118	  /**
119	   * 获取计算节点的输出数量
120	   * @return 计算节点的输出数量
121	   */
122	  size_t GetComputeNodeOutputNum() const {
123	    const auto compute_node_info = GetComputeNodeInfo();
124	    if (compute_node_info == nullptr) {
125	      return 0;
126	    }
127	    return compute_node_info->GetOutputsNum();
128	  }
129	  /**
130	   * 获取计算节点的属性，仅IR原型中定义的属性可被获取到
131	   * @return 计算节点的属性
132	   */
133	  const RuntimeAttrs *GetAttrs() const {
134	    const auto compute_node_info = GetComputeNodeInfo();
135	    if (compute_node_info == nullptr) {
136	      return nullptr;
137	    }
138	    return compute_node_info->GetAttrs();
139	  }
140	  /**
141	   * 获取计算节点的类型
142	   * @return 计算节点的类型
143	   */
144	  const ge::char_t *GetNodeType() const {
145	    const auto compute_node_info = GetComputeNodeInfo();
146	    if (compute_node_info == nullptr) {
147	      return nullptr;
148	    }
149	    return compute_node_info->GetNodeType();
150	  }
151	  /**
152	   * 获取计算节点的name
153	   * @return 计算节点的name
154	   */
155	  const ge::char_t *GetNodeName() const {
156	    const auto compute_node_info = GetComputeNodeInfo();
157	    if (compute_node_info == nullptr) {
158	      return nullptr;
159	    }
160	    return compute_node_info->GetNodeName();
161	  }
162	  /**
163	   * 获取本kernel对应的计算节点的信息
164	   * @return 计算节点的信息
165	   */
166	  const ComputeNodeInfo *GetComputeNodeInfo() const {
167	    return static_cast<const ComputeNodeInfo *>(GetComputeNodeExtend());
168	  }
169	  /**
170	   * 获取本kernel的name
171	   * @return 本kernel的name
172	   */
173	  const ge::char_t *GetKernelName() const {
174	    const auto extend_info = GetExtendInfo();
175	    if (extend_info == nullptr) {
176	      return nullptr;
177	    }
178	    return extend_info->GetKernelName();
179	  }
180	  /**
181	   * 获取本kernel的type
182	   * @return 本kernel的type
183	   */
184	  const ge::char_t *GetKernelType() const {
185	    const auto extend_info = GetExtendInfo();
186	    if (extend_info == nullptr) {
187	      return nullptr;
188	    }
189	    return extend_info->GetKernelType();
190	  }
191	  /**
192	   * 获取本kernel的扩展信息
193	   * @return 本kernel的扩展信息
194	   */
195	  const KernelExtendInfo *GetExtendInfo() const {
196	    return static_cast<const KernelExtendInfo *>(GetKernelExtend());
197	  }
198	
199	 protected:
200	  template <typename T, size_t Offset = 0>
201	  const T *GetDynamicInputPointer(size_t ir_index, size_t relative_ins_index) const {
202	    const auto ins_info = GetIrInputInstanceInfo(ir_index);
203	    if (ins_info == nullptr) {
204	      return nullptr;
205	    }
206	    if (ins_info->GetInstanceNum() <= relative_ins_index) {
207	      return nullptr;
208	    }
209	    return GetInputPointer<T>(Offset + ins_info->GetInstanceStart() + relative_ins_index);
210	  }
211	
212	  template <typename T, size_t Offset = 0>
213	  const T *GetDynamicOutputPointer(size_t ir_index, size_t relative_ins_index) const {
214	    const auto ins_info = GetIrOutputInstanceInfo(ir_index);
215	    if (ins_info == nullptr) {
216	      return nullptr;
217	    }
218	    if (ins_info->GetInstanceNum() <= relative_ins_index) {
219	      return nullptr;
220	    }
221	    const size_t input_num = GetComputeNodeInputNum();
222	    return GetInputPointer<T>(Offset + input_num + ins_info->GetInstanceStart() + relative_ins_index);
223	  }
224	};
225	static_assert(std::is_standard_layout<ExtendedKernelContext>::value,
226	              "The class ExtendedKernelRunContext must be a POD");
227	}  // namespace gert
228	#endif  // METADEF_CXX_INC_EXE_GRAPH_RUNTIME_EXTENDED_KERNEL_CONTEXT_H_
