15	ge::graphStatus ContextBuilderImpl::SetCompileTimeTd(const ContextTensorDesc &desc, CompileTimeTensorDesc &td) const {
16	  td.SetDataType(desc.dtype);
17	  td.SetOriginFormat(desc.origin_format);
18	  td.SetStorageFormat(desc.storage_format);
19	  td.SetExpandDimsType(desc.expand_dims_type);
20	  return ge::GRAPH_SUCCESS;
21	}
22	
23	ge::graphStatus ContextBuilderImpl::InitIOInstanceInfo(ComputeNodeInfo &compute_node_info) {
24	  size_t input_index = 0U;
25	  for (size_t i = 0U; i < op_info_.input_instance.size(); ++i) {
26	    const size_t instance_num = op_info_.input_instance[i];
27	    compute_node_info.MutableInputInstanceInfo(i)->SetInstantiationNum(static_cast<uint32_t>(instance_num));
28	    compute_node_info.MutableInputInstanceInfo(i)->SetInstanceStart(static_cast<uint32_t>(input_index));
29	    input_index += instance_num;
30	  }
31	
32	  size_t output_index = 0U;
33	  for (size_t i = 0U; i < op_info_.output_instance.size(); ++i) {
34	    const size_t instance_num = op_info_.output_instance[i];
35	    compute_node_info.MutableOutputInstanceInfo(i)->SetInstantiationNum(static_cast<uint32_t>(instance_num));
36	    compute_node_info.MutableOutputInstanceInfo(i)->SetInstanceStart(static_cast<uint32_t>(output_index));
37	    output_index += instance_num;
38	  }
39	  return ge::GRAPH_SUCCESS;
40	}
41	
42	ge::graphStatus ContextBuilderImpl::InitCompileTimeTD(ComputeNodeInfo &compute_node_info) {
43	  for (size_t i = 0U; i < compute_node_info.GetInputsNum(); ++i) {
44	    const auto &ctx_io_desc = op_info_.input_tensor_descs[i];
45	    auto td = compute_node_info.MutableInputTdInfo(i);
46	    GE_ASSERT_NOTNULL(td, "tensor desc in compute node info is null");
47	    (void)SetCompileTimeTd(ctx_io_desc, *td);
48	  }
49	
50	  for (size_t i = 0U; i < compute_node_info.GetOutputsNum(); ++i) {
51	    const auto &ctx_io_desc = op_info_.output_tensor_descs[i];
52	    auto td = compute_node_info.MutableOutputTdInfo(i);
53	    GE_ASSERT_NOTNULL(td, "tensor desc in compute node info is null");
54	    (void)SetCompileTimeTd(ctx_io_desc, *td);
55	  }
56	  return ge::SUCCESS;
57	}
58	
59	std::unique_ptr<uint8_t[]> ContextBuilderImpl::CreateComputeNodeInfoImpl(const std::unique_ptr<uint8_t[]> &attr_buf,
60	                                                                         size_t attr_size, const OpInfo &op_info,
61	                                                                         std::vector<std::string> &string_pool,
62	                                                                         size_t &total_size) {
63	  const size_t ir_input_num = op_info.input_ir_num;
64	  const size_t ir_output_num = op_info.output_ir_num;
65	  const size_t input_num = op_info.input_instance_num;
66	  const size_t output_num = op_info.output_instance_num;
67	  GELOGD("opinfo: %s(%s), ir_input_num:%zu, ir_output_num:%zu, input_num:%zu, output_num:%zu.", op_info.op_name.c_str(),
68	         op_info.op_type.c_str(), ir_input_num, ir_output_num, input_num, output_num);
69	  GE_ASSERT_SUCCESS(ComputeNodeInfo::CalcSize(ir_input_num, ir_output_num, input_num, output_num, total_size));
70	  GE_ASSERT_TRUE(!ge::AddOverflow(total_size, attr_size, total_size));
71	  auto compute_node_info_holder = ge::ComGraphMakeUnique<uint8_t[]>(total_size);
72	  GE_ASSERT_NOTNULL(compute_node_info_holder, "Create compute node info holder failed");
73	
74	  const auto idx = string_pool.size();
75	  (void)string_pool.emplace_back(op_info.op_name);
76	  (void)string_pool.emplace_back(op_info.op_type);
77	
78	  auto compute_node_info = ge::PtrToPtr<uint8_t, ComputeNodeInfo>(compute_node_info_holder.get());
79	  compute_node_info->Init(ir_input_num, ir_output_num, input_num, output_num, attr_size, string_pool[idx].c_str(),
80	                          string_pool[idx + 1].c_str());
81	
82	  auto ret = InitIOInstanceInfo(*compute_node_info);
83	  GE_ASSERT_SUCCESS(ret, "Init input instance info for node:%s failed.", op_info.op_name.c_str());
84	
85	  ret = InitCompileTimeTD(*compute_node_info);
86	  GE_ASSERT_SUCCESS(ret, "Init compile time tensor desc for node:%s failed.", op_info.op_name.c_str());
87	
88	  auto attr = compute_node_info->MutableAttrs();
89	  const uint64_t offset = ge::PtrToPtr<RuntimeAttrs, uint8_t>(attr) - compute_node_info_holder.get();
90	  GE_ASSERT_TRUE(
91	      static_cast<size_t>(offset) <= total_size,
92	      "Failed to create kernel context extend info, the offset of attr %zu beyond the total size of ExtendInfo %zu",
93	      offset, total_size);
94	  const uint64_t outputs_ins_info_size = compute_node_info->GetIrOutputsNum() * sizeof(AnchorInstanceInfo);
95	  ret = memcpy_s(ge::PtrToPtr<RuntimeAttrs, uint8_t>(attr),
96	                 static_cast<uint64_t>(total_size - offset - outputs_ins_info_size), attr_buf.get(), attr_size);
97	  GE_ASSERT_SUCCESS(ret, "memcpy_s failed, copy size is %zu, dst size is %zu", attr_size,
98	                    static_cast<uint64_t>(total_size - offset - outputs_ins_info_size));
99	  GELOGI("Node %s, compute_node_info attr_size %zu, outputs_ins_info_size:%zu, offset:%zu, total_size:%zu.",
100	         op_info.op_name.c_str(), attr_size, outputs_ins_info_size, offset, total_size);
101	  return compute_node_info_holder;
102	}
103	ge::graphStatus ContextBuilderImpl::CreateComputeNodeInfo(ContextHolderImpl &holder) {
104	  GE_ASSERT_TRUE((!op_info_.op_type.empty()) && (!op_info_.op_name.empty()) && (op_info_.input_ir_num != 0) &&
105	                     (op_info_.output_ir_num != 0),
106	                 "Invalid params, op_type: %s, op_name: %s, input_num: %u, output_num: %u", op_info_.op_type.c_str(),
107	                 op_info_.op_name.c_str(), op_info_.input_ir_num, op_info_.output_ir_num);
108	  size_t attr_size;
109	  auto attr_buf = bg::CreateAttrBufferWithAttrs(op_info_.attrs, attr_size);
110	
111	  size_t total_size = 0U;
112	  holder.compute_node_info_holder_ =
113	      CreateComputeNodeInfoImpl(attr_buf, attr_size, op_info_, holder.string_pool_, total_size);
114	  return ge::GRAPH_SUCCESS;
115	}
116	ge::graphStatus ContextBuilderImpl::BuildCtx(ContextHolderImpl &holder) {
117	  const auto in_size = input_values_.size();
118	  const auto out_size = output_values_.size();
119	  const uint64_t io_size = in_size + out_size;
120	  const uint64_t size = sizeof(KernelRunContext) + sizeof(Chain *) * (io_size);
121	  holder.context_holder_ = std::make_unique<uint8_t[]>(size);
122	  GE_ASSERT_NOTNULL(holder.context_holder_, "Create context holder failed.");
123	
124	  holder.context_ = ge::PtrToPtr<uint8_t, KernelContext>(holder.context_holder_.get());
125	  auto kernel_run_context = holder.context_->GetContext();
126	  kernel_run_context->input_size = in_size;
127	  kernel_run_context->output_size = out_size;
128	  kernel_run_context->compute_node_info = holder.compute_node_info_holder_.get();
129	  kernel_run_context->output_start = &(kernel_run_context->values[kernel_run_context->input_size]);
130	  holder.value_holder_.resize(io_size);
131	  for (size_t i = 0UL; i < holder.value_holder_.size(); ++i) {
132	    kernel_run_context->values[i] = ge::PtrToPtr<Chain, AsyncAnyValue>(&holder.value_holder_[i]);
133	  }
134	  for (size_t i = 0UL; i < input_values_.size(); ++i) {
135	    holder.value_holder_[i].Set(const_cast<void *>(input_values_[i].first), input_values_[i].second);
136	  }
137	  for (size_t i = 0UL; i < output_values_.size(); ++i) {
138	    holder.value_holder_[input_values_.size() + i].Set(const_cast<void *>(output_values_[i].first),
139	                                                       output_values_[i].second);
140	  }
141	  return ge::GRAPH_SUCCESS;
142	}
143	}  // namespace gert
